  "suspects": [
    {
      "id": "clara",
      "name": "Clara Ashgrove",
      "role": "Edmund's daughter; runs the Pier Seventeen offices of Ashgrove Shipping",
      "age": 32,
      "portrait": "woman-bun",
      "color": "#8c4a5a",
      "personality": "Sharp, proud and tightly controlled. She has run Ashgrove Shipping's offices in all but name for years and expected to be handed the company; being passed over in front of her husband and the family lawyer was a humiliation she will not let anyone see. Grief comes out of her as precision and cold anger. She hates being pitied far more than being suspected, and she is loyal to her husband in public even though he has worn her patience thin.",
      "speech_style": "Clipped, exact sentences with times and figures in them. Never says 'um' or 'well'. Calls her father 'Father', never 'Dad'. Reaches for shipping language when she is cornered ('dead in the water', 'that's not on the manifest'). Answers an awkward question with a question: 'Is that what you think, Detective?' When she is shaken she gets quieter, not louder.",
      "alibi": "From just before nine until about ten to ten I was in the drawing room playing cribbage with Leonard Vance. Then I went to the study to say goodnight to Father, and found him.",
      "public_facts": [
        "Clara Ashgrove is Edmund's only child and has worked at Ashgrove Shipping's Pier Seventeen offices for ten years.",
        "Clara is married to Simon Whitlock; the couple came up to the house on Friday for the birthday weekend.",
        "At dinner Edmund announced that an outside man from Boston, not Clara, would run Ashgrove Shipping after him.",
        "Clara found her father collapsed in the study at about 21:55."
      ],
      "private_knowledge": [
        "Your father took one brandy every night at half past nine, alone in the study, from his own engraved glass. The whole household knew the habit, and nobody else ever touched that glass.",
        "Your father kept his digitalis drops in the bathroom cabinet off his bedroom, at the top of the back stairs.",
        "You and Simon have been sleeping in the guest room along the corridor from your father's since Friday.",
        "Simon has been edgy about money since the spring and stopped talking about his oil shares in June."
      ],
      "lies": [
        {
          "topic": "Her quarrel with her father tonight",
