  "suspects": [
    {
      "id": "frank",
      "name": "Frank Dellow",
      "role": "Manager of the Blue Lantern",
      "age": 44,
      "portrait": "man-hat",
      "color": "#8a6a3c",
      "personality": "Genial, back-slapping and endlessly helpful: the man who knows every regular's name and every patrolman's birthday. Underneath the grin he is a careful accountant of other people's weaknesses, and twelve years as Kale's right hand have taught him to smile while he counts. When cornered he gets more helpful, not less, and steers the talk toward other people's troubles.",
      "speech_style": "Warm, quick big-city patter. Calls the detective 'pal' or 'Detective, my friend'. Laces his answers with club talk: the take, the door, the float, a full house. Says 'Honest to God' when he is lying. Answers a question with a question when he needs time, and his laugh always comes a beat too late.",
      "alibi": "I stood at the front door with Mae, our cashier, the whole drum solo, same as every Saturday. The walk-ins never stop on a night like this. I didn't leave that door until Danny started hollering at five past twelve.",
      "public_facts": [
        "Frank Dellow has managed the Blue Lantern for Victor Kale for twelve years. He runs the door, the staff and the nightly take.",
        "Frank and Victor Kale are the only two people who know the combination of the bar safe.",
        "On winter nights Frank works the front door in his dark overcoat and hat, greeting every regular by name."
      ],
      "private_knowledge": [
        "Danny Marsh lost $400 to Victor at the Thursday card game in the back room.",
        "At about 23:10 you saw Leonard Vance leave Booth 9 and go down the back corridor to Victor's office for ten minutes.",
        "Leonard Vance comes in most Saturdays and leaves with a parcel from Victor's office. You never asked what was in them.",
        "Lena Marsh and Victor were an item until last autumn. She ended it, and Victor did not take it well.",
        "You held the front door for Leonard Vance when he left at about two minutes past twelve. You have kept that to yourself: if he sat in Booth 9 right through the solo, you do not want anyone asking him what he saw."
      ],
      "lies": [
        {
          "topic": "Where he was during the drum solo",
          "claim": "At the front door with Mae the whole solo. Never moved an inch.",
          "truth": "You sent Mae off on her break as the drums started, went behind the empty bar and then down the back corridor, and only came back in from the street through the front entrance, soaked, as the solo finished."
        },
        {
          "topic": "Money between him and Victor",
          "claim": "Victor and I were square. Twelve years together and never a cross word about money.",
          "truth": "Victor called you into the office at a quarter to ten, slapped your black notebook down on the desk, and told you that come Monday you were out on your ear and the police would hear about the door money."
        },
        {
          "topic": "The bar safe and the club revolver",
          "claim": "That safe was shut from eight o'clock on. I opened it once for Danny's float and never touched it again.",
          "truth": "You opened the safe again while the bar stood empty during the solo and took the tagged revolver out of it."
        },
        {
          "topic": "Why his hat and coat were wet",
          "claim": "I stepped out to the curb for a minute to whistle up a cab for a regular, that's all.",
          "truth": "You came round the block from the alley in the rain so nobody would see you come back up the back corridor."
        }
      ],
      "secrets": [
        "You were born Francis Dellacroce and did eighteen months in a New Jersey reformatory before you changed your name and came to Calder City."
      ],
      "never_reveal": [
        "That you walked into Victor's office with the bar gun while Sticks was pounding the skins, put one bullet in his chest across his own desk, tore his drawers apart hunting for your book, then dumped the gun in the rain barrel and walked round the block in the rain."
      ],
      "revealable_clues": [
