      "revealable_clues": [
        {
          "clue_id": "vance-kale-alive",
          "text": "Confirms he called on Victor in the office at about 23:10 on what he calls club business, and found him alive, cheerful and impatient to get back to the show.",
          "condition": "free"
        },
        {
          "clue_id": "vance-clean-house",
          "text": "Says that on Friday Victor told him he had caught one of his own people with a hand in the till for the better part of a year, and meant to clean house on Monday. Victor would not say who.",
